Definition fh_exit_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c : pcore) (pad7 pad2 ej j24 : list byte) (g : bool),
  rw_cells usegs m1 (bv_unsigned sp + -48) [CB 24 j24] ->
  rw_cells usegs m1 (bv_unsigned sp + -24) [C8 s1v; C8 s0v; C8 ra] ->
  rw_cells usegs m1 P (ParserCoreCells c pad7 pad2) ->
  rw_cells usegs m1 E [CB 24 ej] ->
  HttpCat m1 g -> XStatics m1 ->
  stk usegs m1 lo (bv_unsigned sp + -48) -> lo + 80 <= bv_unsigned sp -> 0xb8000 <= lo ->
  bv_unsigned sp <= P -> P + 80 <= 2^64 -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (P + 80 <= E \/ E + 24 <= P) ->
  munch (body_W lo sp P E) m m1 -> wmono usegs m m1 -> mem_inv usegs m1 ->
  evt usegs (fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells usegs m' E (ErrCodeCells (EC_http_loc e loc))
    /\ HttpCat m' true /\ XStatics m')
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (wz E) (wz P) a0x a1 a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom usegs)).

