  intros rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P E lo c pad7 pad2 ej j24 g;
  intros FRlo FRhi PC EC HC XS ST LO IMG PLO PHI ELO EHI DPE MU WM MI;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold body_W, G_HTTP_CAT in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC; unfold wz in *;
  (* [comment removed for export] *)
  steps_to 0x34360%Z;
  call_assignA_with (bv_unsigned sp + -48) (bv_unsigned sp + -48) e lo g j24;
  clear HC XS;
  lazymatch goal with
  | TMP : rw_cells _ _ (bv_unsigned sp + -48) (ErrCodeCells _), HC : HttpCat _ true, XS : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP;
    (* [comment removed for export] *)
    steps_to 0x3db10%Z;
    expose_statics HC XS [(lo, bv_unsigned sp); (E, E + 24)]%Z;
    (* [comment removed for export] *)
    st1; st1; st1;
    (* [comment removed for export] *)
    step; step; step;
    join_frame TMP FRhi (bv_unsigned sp + -48);
    step; release_frame TMP ST' (bv_unsigned sp); step;
    lazymatch goal with
    | MU2 : munch [(lo, bv_unsigned sp); (E, E + 24)]%Z ?mx _, WM2 : wmono _ ?mx _ |- _ =>
        finish; [ close_HttpCat_chunks | close_XStatics XS MU2 WM2 ]
    end
  end.
