Lemma fh_assigns_http : forall c e loc c', fh_res c = (EC_http_loc e loc, c') -> fh_assigns c = true.
Proof. intros c e loc c' R. unfold fh_assigns. rewrite R. reflexivity. Qed.
Lemma fh_assigns_clear : forall c c', fh_res c = (EC_clear, c') -> fh_assigns c = false.
Proof. intros c c' R. unfold fh_assigns. rewrite R. reflexivity. Qed.

