Local Ltac fh_prepare FR HC XS MUq WM :=
  let FRlo := fresh "FRlo" in let FRhi := fresh "FRhi" in let HC' := fresh "HC'" in let XS' := fresh "XS'" in
  lazymatch type of FR with rw_cells _ ?mx _ [CB 24 ?j24; C8 ?x1; C8 ?x2; C8 ?x3] =>
    split_frame FR [CB 24 j24] [C8 x1; C8 x2; C8 x3] FRlo FRhi;
    pose proof (HttpCat_transport _ _ _ _ HC MUq WM ltac:(unfold G_HTTP_CAT; cbn; lia) ltac:(unfold G_HTTP_CAT_GUARD; cbn; lia)) as HC';
    pose proof (XStatics_transport _ _ _ XS MUq WM ltac:(repeat constructor; cbn; lia)) as XS';
    clear HC XS MUq
  end.

(* [comment removed for export] *)
Local Ltac fh_close R L :=
  unfold fh_post; rewrite R;
  first [ rewrite (fh_assigns_http _ _ _ _ R) | rewrite (fh_assigns_clear _ _ R) ]; cbn [fst snd orb];
  let X := fresh "EX" in pose proof L as X; unfold fh_exit_stmt, fh_join_stmt in X;
  eapply X; clear X; try eassumption; try (cbn [pc_state pc_set_state pc_set_state_f]; lia).

(* [comment removed for export] *)
Local Ltac fh_R R c PAIR :=
  assert (R : fh_res c = PAIR);
  [ unfold fh_res; cbv zeta;
    repeat match goal with H : Z.testbit _ _ = _ |- _ => rewrite H end;
    repeat match goal with
    | |- context [?a =? ?b] => first [ replace (a =? b) with true by (symmetry; apply Z.eqb_eq; lia)
                                     | replace (a =? b) with false by (symmetry; apply Z.eqb_neq; lia) ]
    | |- context [?a <? ?b] => first [ replace (a <? b) with true by (symmetry; apply Z.ltb_lt; lia)
                                     | replace (a <? b) with false by (symmetry; apply Z.ltb_ge; lia) ]
    end;
    cbn [andb negb]; reflexivity
  | ].

